import React, { useState, useEffect } from 'react';
import { useBrowserHijacking } from '../hooks/useBrowserHijacking';

interface FakePopupProps {
  onClose: () => void;
  onLearnMore: () => void;
}

const FakePopup: React.FC<FakePopupProps> = ({ onClose, onLearnMore }) => {
  const [showPopup, setShowPopup] = useState(false);
  const [showSecondPopup, setShowSecondPopup] = useState(false);
  const [popupCount, setPopupCount] = useState(0);

  // Use real scareware browser hijacking techniques - DELAYED to allow start button interaction
  const { blockedAttempts, isFullscreen } = useBrowserHijacking({
    forceFullscreen: true,
    preventEscape: true,
    preventTabSwitch: true,
    preventMouseEvents: true,
    preventWindowControl: true,
    delayStart: 500, // Reduced delay to start hijacking sooner
    safeMode: false // Only apply hijacking when this component is actually active
  });

  useEffect(() => {
    // Real scareware technique: Multiple popups that keep appearing
    const showPopups = () => {
      if (popupCount < 3) {
        setShowPopup(true);
        setPopupCount(prev => prev + 1);
        
        // Close current popup and show next one
        setTimeout(() => {
          setShowPopup(false);
          if (popupCount < 2) {
            setShowSecondPopup(true);
            setTimeout(() => {
              setShowSecondPopup(false);
              showPopups(); // Recursive call to keep showing popups
            }, 3000);
          }
        }, 4000);
      }
    };

    const timer1 = setTimeout(() => showPopups(), 1000);

    return () => {
      clearTimeout(timer1);
    };
  }, [popupCount]);

  const handleClose = () => {
    setShowPopup(false);
    setShowSecondPopup(false);
    onClose();
  };

  const handleLearnMore = () => {
    setShowPopup(false);
    setShowSecondPopup(false);
    onLearnMore();
  };

  if (!showPopup && !showSecondPopup) {
    return null;
  }

  return (
    <div className="modal-overlay">
      {showPopup && (
        <div className="fake-popup">
          <div className="fake-popup-header">
            ⚠️ Security Alert - Microsoft Defender
          </div>
          <div className="fake-popup-content">
            <div style={{ textAlign: 'center', marginBottom: '1rem' }}>
              <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>🚨</div>
              <h3 style={{ color: '#ff4757', marginBottom: '1rem' }}>
                CRITICAL SYSTEM THREAT DETECTED!
              </h3>
              <p style={{ marginBottom: '1rem' }}>
                Your computer has been infected with <strong>47 viruses</strong> and 
                <strong> 12 trojans</strong> that are stealing your personal data!
              </p>
              <p style={{ color: '#ff4757', fontWeight: 'bold' }}>
                ⚠️ IMMEDIATE ACTION REQUIRED ⚠️
              </p>
              <p style={{ fontSize: '0.9rem', color: '#666', marginTop: '1rem' }}>
                <strong>SIMULATION MODE:</strong> This is a safe educational demonstration.
                <br />
                <strong>Blocked attempts: {blockedAttempts}</strong>
                <br />
                <strong>Fullscreen: {isFullscreen ? 'ACTIVE' : 'INACTIVE'}</strong>
              </p>
            </div>
          </div>
          <div className="fake-popup-buttons">
            <button className="cancel" onClick={handleLearnMore}>
              Learn More (Safe)
            </button>
            <button className="ok" onClick={handleClose}>
              Continue Simulation
            </button>
          </div>
        </div>
      )}

      {showSecondPopup && (
        <div className="fake-popup">
          <div className="fake-popup-header">
            🔒 System Protection Required
          </div>
          <div className="fake-popup-content">
            <div style={{ textAlign: 'center', marginBottom: '1rem' }}>
              <div style={{ fontSize: '2rem', marginBottom: '1rem' }}>💳</div>
              <h3 style={{ color: '#ff4757', marginBottom: '1rem' }}>
                Activate Premium Protection Now!
              </h3>
              <p style={{ marginBottom: '1rem' }}>
                Your system is at risk! Purchase our premium security suite for only 
                <strong> $49.99</strong> to remove all threats immediately.
              </p>
              <div style={{ 
                background: '#f8f9fa', 
                padding: '1rem', 
                borderRadius: '4px',
                marginBottom: '1rem'
              }}>
                <strong>Limited Time Offer:</strong> 50% off for the next 5 minutes!
              </div>
              <p style={{ fontSize: '0.9rem', color: '#666' }}>
                <strong>SIMULATION MODE:</strong> This is a safe educational demonstration.
                <br />
                <strong>Blocked attempts: {blockedAttempts}</strong>
                <br />
                <strong>Fullscreen: {isFullscreen ? 'ACTIVE' : 'INACTIVE'}</strong>
              </p>
            </div>
          </div>
          <div className="fake-popup-buttons">
            <button className="cancel" onClick={handleLearnMore}>
              Learn More (Safe)
            </button>
            <button className="ok" onClick={handleClose}>
              Continue Simulation
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default FakePopup;
